// 실패한 Execution 정보 정리 + 비밀값 가리기 + error_type 분류 (TECH 14.12, 15.21)
const e = $input.first().json;
const exec = e.execution || {};
const wf = e.workflow || {};
const trig = e.trigger || {};
const raw = String(exec.error?.message || trig.error?.message || 'unknown error');
const redact = (s) => s
  .replace(/eyJ[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[REDACTED]')
  .replace(/sb_(secret|publishable)_[A-Za-z0-9_-]+/g, '[REDACTED]')
  .replace(/sk-ant-[A-Za-z0-9_-]+/g, '[REDACTED]')
  .replace(/(bearer)\s+[A-Za-z0-9._~+\/=-]+/gi, '$1 [REDACTED]');
const message = redact(raw).slice(0, 1000);
const httpCode = String(exec.error?.httpCode ?? '');
const lower = `${httpCode} ${message} ${String(exec.error?.description || '')}`.toLowerCase();
let error_type = 'unknown', error_code = 'N8N_WORKFLOW_ERROR', retryable = true;
if (/timeout|timed out|etimedout|esockettimedout/.test(lower)) { error_type = 'timeout'; error_code = 'TIMEOUT'; }
else if (/econnreset|econnrefused|enotfound|socket hang up|network/.test(lower)) { error_type = 'transient'; error_code = 'NETWORK_ERROR'; }
else if (/\b429\b|rate limit/.test(lower)) { error_type = 'api'; error_code = 'RATE_LIMIT'; }
else if (/\b5\d\d\b|service unavailable|bad gateway/.test(lower)) { error_type = 'api'; error_code = 'TEMPORARY_API_ERROR'; }
else if (/\b401\b|\b403\b|unauthorized|forbidden|authorization failed/.test(lower)) { error_type = 'authentication'; error_code = 'INVALID_AUTH'; retryable = false; }
const workflow_name = String(wf.name || 'unknown workflow');
const last_node = String(exec.lastNodeExecuted || trig.node?.name || 'unknown node');
return [{ json: {
  execution_id: exec.id ? String(exec.id) : null,
  workflow_name, last_node,
  step: last_node.slice(0, 100),
  message: `[${workflow_name} / ${last_node}] ${message}`.slice(0, 1000),
  error_type, error_code, retryable
} }];

// 각 Workflow가 선점 직후 남긴 CLAIM 기록에서 Job ID와 locked_at을 찾는다
const info = $('오류 정리').first().json;
const r = $input.first().json;
const row = (r.statusCode === 200 && Array.isArray(r.body)) ? r.body[0] : null;
return [{ json: { ...info, job_id: row?.automation_job_id || '', locked_at: row?.input_data?.locked_at || '' } }];
